using He_Thong_GYM.BLL;using He_Thong_GYM.Helpers;using He_Thong_GYM.Models;
namespace He_Thong_GYM.Forms;
public partial class FrmDangKyPT:Form
{private readonly DangKyBLL _bll=new();public FrmDangKyPT(){InitializeComponent();}
 private async void FrmDangKyPT_Load(object? s,EventArgs e){try{cboThanhVien.DataSource=await _bll.LayThanhVienAsync();cboThanhVien.DisplayMember=nameof(ThanhVien.HoTen);cboThanhVien.ValueMember=nameof(ThanhVien.MaTV);cboHLV.DataSource=await _bll.LayHLVAsync();cboHLV.DisplayMember=nameof(HuanLuyenVien.HoTen);cboHLV.ValueMember=nameof(HuanLuyenVien.MaHLV);cboKhuyenMai.DataSource=await _bll.LayKhuyenMaiAsync();cboKhuyenMai.DisplayMember=nameof(KhuyenMai.TenKM);cboKhuyenMai.ValueMember=nameof(KhuyenMai.MaKM);TinhGia();dgvLichSu.DataSource=await _bll.LayLichSuPTAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Lỗi dữ liệu",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 private void TinhGia(){if(cboHLV.SelectedItem is not HuanLuyenVien h)return;var km=cboKhuyenMai.SelectedItem as KhuyenMai;dtpKetThuc.Value=dtpBatDau.Value.AddDays((int)nudSoBuoi.Value*7);lblTongTien.Text=$"{(h.PhiThue??0)*nudSoBuoi.Value*(1-(km?.PhanTramGiam??0)/100):N0} đ";}
 private async void btnDangKy_Click(object? s,EventArgs e){try{if(SessionManager.NguoiDungHienTai is null)throw new InvalidOperationException("Chưa có phiên đăng nhập.");if(cboThanhVien.SelectedItem is not ThanhVien tv||cboHLV.SelectedItem is not HuanLuyenVien h)throw new InvalidOperationException("Hãy chọn thành viên và huấn luyện viên.");var km=cboKhuyenMai.SelectedItem as KhuyenMai;var kq=await _bll.DangKyPTAsync(tv.MaTV,h.MaHLV,(int)nudSoBuoi.Value,km?.MaKM,dtpBatDau.Value,dtpKetThuc.Value,SessionManager.NguoiDungHienTai.MaNV);dgvLichSu.DataSource=await _bll.LayLichSuPTAsync();MessageBox.Show($"Đã đăng ký PT. Hóa đơn #{kq.Item2} đang chờ thanh toán.","Thành công",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(ex.Message,"Không thể đăng ký",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 private void GiaThayDoi(object? s,EventArgs e)=>TinhGia();}
